templates.script:
set -euo pipefail
[ $# -eq 3 ] || { echo "grep-count: needs <pattern> <file> <min>" >&2; exit 2; }
pat="$1"; file="$2"; min="$3"
case "$min" in ''|*[!0-9]*) echo "grep-count: min must be a positive integer" >&2; exit 2 ;; esac
[ "$min" -ge 1 ] || { echo "grep-count: min=0 is vacuous -- min must be >= 1" >&2; exit 2; }
[ -f "$file" ] || { echo "grep-count: no such file: $file" >&2; exit 1; }
n=$(grep -cE -- "$pat" "$file" || true)
n=${n:-0}
[ "$n" -ge "$min" ] || { echo "grep-count: found $n < $min of /$pat/ in $file" >&2; exit 1; }
echo "found $n of >=$min required"
exit 0

set -euo pipefail
[ $# -ge 1 ] || { echo "named-test: needs <script-path>" >&2; exit 2; }
script="$1"; shift
[ -f "$script" ] || { echo "named-test: no such script: $script" >&2; exit 1; }
bash "$script" "$@"
